package vn.covie.catalog.model;
import jakarta.persistence.*;
@Entity @Table(name="catalog_item_tags") public class CatalogItemTagEntity { @EmbeddedId private CatalogItemTagId id; @MapsId("catalogItemId") @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="catalog_item_id",nullable=false) private CatalogItemEntity catalogItem; @MapsId("tagId") @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="tag_id",nullable=false) private TagEntity tag; protected CatalogItemTagEntity(){} public static CatalogItemTagEntity associate(CatalogItemEntity catalogItem,TagEntity tag){CatalogItemTagEntity association=new CatalogItemTagEntity();association.id=new CatalogItemTagId(catalogItem.getId(),tag.getId());association.catalogItem=catalogItem;association.tag=tag;return association;} public CatalogItemTagId getId(){return id;} }
